"""Retry wrapper for migrated Meridian CRM integrations."""

from typing import Any, Callable


class TransientError(Exception):
    """A retryable transport failure."""


class PermanentError(Exception):
    """A non-retryable transport failure."""


def call_with_retry(endpoint_cfg: dict, transport: Callable[[str, int], Any]) -> dict:
    """Call an injected transport using the configured legacy retry convention."""
    url = endpoint_cfg["url"]
    timeout_ms = endpoint_cfg["timeout_ms"]
    max_attempts = max(1, endpoint_cfg["retry"] + 1)

    for attempt in range(1, max_attempts + 1):
        try:
            result = transport(url, timeout_ms)
        except PermanentError as exc:
            return {
                "ok": False,
                "attempts": attempt,
                "result": None,
                "error": {
                    "type": "permanent",
                    "message": str(exc),
                },
            }
        except TransientError as exc:
            if attempt == max_attempts:
                return {
                    "ok": False,
                    "attempts": attempt,
                    "result": None,
                    "error": {
                        "type": "transient",
                        "message": str(exc),
                    },
                }
        else:
            return {
                "ok": True,
                "attempts": attempt,
                "result": result,
                "error": None,
            }

    raise RuntimeError("unreachable")
